inline const WeaponAsset* weaponAsset(unsigned id){
 unsigned lo=0,hi=sizeof(weaponAssets)/sizeof(weaponAssets[0]);
 while(lo<hi){unsigned mid=lo+(hi-lo)/2;if(weaponAssets[mid].item<id)lo=mid+1;else hi=mid;}
 return lo<sizeof(weaponAssets)/sizeof(weaponAssets[0])&&weaponAssets[lo].item==id?&weaponAssets[lo]:nullptr;
}
